import type { StudentWalletStatusKey } from "@/lib/key-value-pairs/key-value-pair-types";

/**
 * Type: Response
 * Description: Represents a payment concept associated with a student's wallet for a specific academic cycle, containing details about the payment, its status, and references to related entities.
 */
export interface StudentWalletItemResponse {
    /**
     * Unique identifier for the academic cycle wallet, generated by backend
     */
    id: string;
    /**
     * Payment concept name.
     */
    name: string;
    /**
     * Payment concept code.
     */
    code: string;
    /**
     * Due date for the payment associated with the academic cycle wallet as an ISO string (YYYY-MM-DDTHH:mm:ss.mmmZ)
     */
    dueDate: string;
    /**
     * Description of the payment concept
     */
    description?: string;
    /**
     * Amount for the payment associated with the academic cycle wallet
     */
    amount: number;
    /**
     * Indicates if forgiveness is allowed for the payment associated with the academic cycle wallet
     */
    allowForgiveness: boolean;
    /**
     * Outstanding amount for the payment associated with the academic cycle wallet
     */
    outstandingAmount: number;
    /**
     * Indicates if the payment associated with the student wallet has been forgiven.
     */
    isForgiven?: boolean;
    /**
     * Date when the payment associated with the student wallet is extended
     */
    extensionDate?: string;
    /**
     * Current status of the payment associated with the academic cycle wallet
     */
    status: StudentWalletStatusKey;
    /**
     * Identifier of the associated academic cycle enrollment
     */
    academicCycleEnrollmentId: string;
    /**
     * Identifier of the associated academic cycle
     */
    academicCycleId: string;
    /**
     * Identifier of the associated student
     */
    studentId: string;
    /**
     * Identifier of the associated academic cycle wallet payment concept
     */
    academicCycleWalletId: string;
}
